// (Center of stripe, width of stripe)
const vec2 HEIGHT_PCT_BLACK = vec2(.00, .24);
const vec2 HEIGHT_PCT_WHITE = vec2(.185, .015);
const float RADIUS_PCT_WHITE = .335;
const float RADIUS_PCT_BLACK = .255;

const float STAR_POINTS = 6.;

const vec3 BACKGROUND_COLOR = vec3(1.);
const vec3 FOREGROUND_COLOR = vec3(0.);
const vec3 ACCENT_COLOR = vec3(.8,.63,.21);

const bool SWING_AROUND = false;

const float PI = 3.14159;

vec3 color_interp(float value, float fence, vec3 foreground, vec3 background, float delta) {
    return mix(background, foreground, 1.0-smoothstep(fence-delta, fence+delta, value));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 st = gl_FragCoord.xy;
    float scale = min(iResolution.x, iResolution.y);
    st /= scale;
    st -= (iResolution.xy/scale * .5) - .5;

    vec3 color = BACKGROUND_COLOR;
    float height_pct = abs(st.y-0.5);
    float dist_center = length(st - vec2(.5));

    color = color_interp(abs(height_pct - HEIGHT_PCT_BLACK[0]), HEIGHT_PCT_BLACK[1], FOREGROUND_COLOR, color, 0.001);
    color = color_interp(abs(height_pct - HEIGHT_PCT_WHITE[0]), HEIGHT_PCT_WHITE[1], BACKGROUND_COLOR, color, 0.001);
    color = color_interp(dist_center, RADIUS_PCT_WHITE, BACKGROUND_COLOR, color, 0.001);
    color = color_interp(dist_center, RADIUS_PCT_BLACK, FOREGROUND_COLOR, color, 0.001);
    float initial_angle = SWING_AROUND ? fract(iTime) : 0.;
    for (float degree=initial_angle; degree<=2.*PI; degree+=1./STAR_POINTS*2.*PI){
        vec2 xy = st - vec2(.5);
        xy *= mat2(cos(degree), -sin(degree),
                   sin(degree),  cos(degree));
    	color = (xy.y > 0.) && (xy.y <= 4.85 * xy.x + .17) && (xy.y <= -4.85 * xy.x + .17) ? ACCENT_COLOR : color;
    }

    fragColor = vec4(color,1.0);
}
